{
  "name": "实时绘图客户端",
  "name_en": "Live Plot Client",
  "manufacturer": "",
  "description": "用于实验室测量过程中的实时数据可视化客户端，可显示一维曲线、XY 曲线和二维伪彩图/热图，并支持追加数据、清空、隐藏、移除和文本标注等操作，便于在线监测实验信号与扫描结果。",
  "description_en": "A real-time data visualization client for laboratory measurements. It displays 1D traces, XY curves, and 2D pseudocolor/heatmap data, and supports appending data, clearing, hiding, removing, and adding text labels for live monitoring of signals and scan results.",
  "tag_hints": [
    "live plotting",
    "laboratory data visualization",
    "real-time monitoring",
    "1D curve plotting",
    "XY plotting",
    "2D heatmap visualization"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭实时绘图客户端。",
      "description_en": "Close the live plotting client."
    },
    {
      "action_name": "auto-send_to_plotter",
      "description": "向绘图器发送数据和元数据。",
      "description_en": "Send data and metadata to the plotter."
    },
    {
      "action_name": "auto-plot_y",
      "description": "绘制或更新一维 Y 数据曲线。",
      "description_en": "Plot or update a 1D Y-data trace."
    },
    {
      "action_name": "auto-plot_z",
      "description": "绘制或更新二维 Z 数据图像/热图。",
      "description_en": "Plot or update a 2D Z-data image/heatmap."
    },
    {
      "action_name": "auto-plot_xy",
      "description": "绘制或更新 XY 数据曲线。",
      "description_en": "Plot or update XY data curves."
    },
    {
      "action_name": "auto-append_y",
      "description": "向一维 Y 曲线追加一个数据点。",
      "description_en": "Append one data point to a 1D Y trace."
    },
    {
      "action_name": "auto-append_xy",
      "description": "向 XY 曲线追加一个坐标点。",
      "description_en": "Append one coordinate point to an XY trace."
    },
    {
      "action_name": "auto-append_z",
      "description": "向二维 Z 数据图追加一行或一块数据。",
      "description_en": "Append a row or block of data to a 2D Z-data plot."
    },
    {
      "action_name": "auto-label",
      "description": "为指定图形设置文本标签或注释。",
      "description_en": "Set a text label or annotation for a specified plot."
    },
    {
      "action_name": "auto-clear",
      "description": "清空指定图形或全部图形的数据。",
      "description_en": "Clear the data of a specified plot or all plots."
    },
    {
      "action_name": "auto-hide",
      "description": "隐藏指定图形或全部图形。",
      "description_en": "Hide a specified plot or all plots."
    },
    {
      "action_name": "auto-remove",
      "description": "移除指定图形或全部图形。",
      "description_en": "Remove a specified plot or all plots."
    },
    {
      "action_name": "auto-disconnect_received",
      "description": "处理绘图器断开连接事件。",
      "description_en": "Handle a plotter disconnection event."
    }
  ]
}

